const src = 'https://www.youtube.com/watch?v=EXAMPLE1234';
const base = ($env.N8N_WEBHOOK_BASE || 'https://your-n8n.example.com').replace(/\/+$/, '');
const token = Buffer.from(src, 'utf8').toString('base64');
const callback_url = base + '/webhook/openshorts-callback?src=' + encodeURIComponent(token);
return [{ json: { source_url: src, callback_url } }];

const j = $input.first().json;
const e = [];
try { const u = new URL(j.source_url); if (!/^https?:$/.test(u.protocol)) e.push('source_url must be http(s)'); } catch { e.push('source_url must be a valid URL'); }
try { new URL(j.callback_url); } catch { e.push('callback_url must be a valid URL reachable by OpenShorts'); }
if (e.length) throw new Error('Invalid input: ' + e.join('; '));
return [{ json: j }];

const r = $json || {};
const job_id = r.job_id || r.id || null;
if (!job_id) throw new Error('OpenShorts /api/process did not return job_id; verify API version before trusting this run');
return [{ json: { job_id, status: 'submitted', source_url: $('Validate Submit').item.json.source_url, submitted_at: new Date().toISOString() } }];

const crypto = require('crypto');
const item = $input.first().json || {};
const headers = item.headers || {};
const secret = $env.OPENSHORTS_WEBHOOK_SECRET || '';
const sigHeader = headers['x-openshorts-signature'] || headers['X-OpenShorts-Signature'] || '';
// Raw body: with webhook option rawBody:true, n8n exposes the raw payload string.
const raw = (typeof item.rawBody === 'string' && item.rawBody) || (item.body && typeof item.body === 'string' ? item.body : JSON.stringify(item.body || {}));
if (secret) {
  if (!sigHeader) throw new Error('Callback missing X-OpenShorts-Signature but a webhook_secret is configured (fail closed)');
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
  const a = Buffer.from(sigHeader); const b = Buffer.from(expected);
  const okLen = a.length === b.length;
  if (!okLen || !crypto.timingSafeEqual(a, b)) throw new Error('Callback HMAC signature mismatch (rejected). If bodies differ byte-wise, ensure the webhook Raw Body option is on and no proxy rewrites the payload.');
}
// Source correlation from the ?src= token we set at submit time.
const query = item.query || {};
let source_url = '';
try { source_url = query.src ? Buffer.from(decodeURIComponent(query.src), 'base64').toString('utf8') : ''; } catch (e) { source_url = ''; }
const body = (typeof item.body === 'object' && item.body) ? item.body : JSON.parse(raw || '{}');
return [{ json: { verified: !!secret, source_url, event: body.event || '', job_id: body.job_id || null, clips: Array.isArray(body.clips) ? body.clips : [] } }];

const j = $input.first().json;
if (!j.job_id) throw new Error('Callback missing job_id');
if (j.event && j.event !== 'job.completed') return [{ json: { job_id: j.job_id, ignored_event: j.event } }];
if (!j.clips.length) throw new Error('Callback for job ' + j.job_id + ' contained no clips');
const seen = new Set();
const organised = [];
for (const c of j.clips) {
  const key = (c.download_url || c.video_url || (j.job_id + ':' + c.index)).toString();
  if (seen.has(key)) continue; seen.add(key);
  organised.push({ clip_id: j.job_id + ':' + (c.index ?? organised.length), index: c.index ?? null, title: c.title || '', video_url: c.video_url || '', download_url: c.download_url || '', status: 'ready_for_review' });
}
return [{ json: { job_id: j.job_id, source_url: j.source_url, clip_count: organised.length, clips: organised, posting: 'DRAFT/APPROVAL ONLY - review before any upload' } }];
